/**
 * Tiketin-UTS — Data tiket simulasi (dummy)
 * Sumber data hanya untuk keperluan pembelajaran UTS Struktur Data.
 * Format: ES module.
 *
 * transportType konsisten dengan src/data/cities.js: "plane" | "train" | "bus".
 * origin & destination = name kota persis seperti di cities.js.
 *
 * Lokasi rute kini dirujuk lewat ID di src/data/locations.js sesuai transportasi:
 * - plane : originLocationId/destinationLocationId -> id bandara (airport-*)
 * - train : originLocationId/destinationLocationId -> id stasiun (station-*)
 * - bus   : originLocationId/destinationLocationId -> id terminal (terminal-*)
 *
 * Field tambahan per transportasi:
 * - plane: flightNo (SIMULASI), baggageKg, stops (0 = langsung)
 * - bus  : facilities[], capacity, bookedSeats[] (peta kursi simulasi)
 * Nama kota, harga, jadwal, kursi, dan nomor penerbangan adalah data simulasi;
 * tidak terhubung ke sistem reservasi resmi mana pun.
 *
 * Jumlah: 902 tiket — seluruhnya data simulasi tugas kuliah, bukan jadwal resmi:
 * - 30 data awal (tidak diubah) + 78 jadwal pada blok "GENERATED-EXTRA-TICKETS"
 *   (tiap rute lama mendapat keberangkatan D+2 dan D+4 sehingga jendela
 *   20-31 Okt 2026 terisi; 15 rute arah-balik untuk pencarian pulang-pergi)
 *   + 4 jadwal pada blok "HALIM-EXTRA-TICKETS" (rute Bandara Halim / HLP).
 * - 582 jadwal pada blok "DENSE-EXTRA-TICKETS" (dihasilkan skrip generator):
 *   Bagian A — setiap kombinasi rute+tanggal yang sudah ada di-top-up menjadi
 *   minimal 4 tiket (rute populer 5-6) dengan operator, jam berangkat unik,
 *   harga, durasi, kelas, dan kursi BERBEDA — bukan tiket kembar — agar
 *   pencarian menghasilkan banyak pilihan dan fitur sorting dapat diuji.
 *   Bagian B — jendela awal Oktober 2026 (1-14 Okt): tiap rute punya jadwal;
 *   tanggal 15-19 Okt 2026 sengaja dikosongkan sebagai uji pencarian tanpa hasil.
 * - 208 jadwal pada blok "NEW-ROUTES-TICKETS" (dihasilkan skrip): 15 rute populer
 *   yang sebelumnya TIDAK ADA sama sekali — pesawat CGK<->SUB, CGK<->YIA,
 *   SUB<->DPS, KNO->CGK, CGK<->BPN; kereta Gambir<->Yogyakarta,
 *   Gubeng<->Yogyakarta; bus Pulo Gebang<->Bungurasih — masing-masing 4 tiket
 *   per tanggal dengan variasi operator/jam/harga/durasi/kelas/kursi.
 */

